const body = items[0].json.body || items[0].json;

if (!body.business_id) {
  throw new Error('Missing business_id — the website must supply the RLS-verified business_id of the logged-in user.');
}
if (!body.first_name) {
  throw new Error('Missing first_name.');
}

const hasFile = !!body.photo_base64;
const ext = hasFile ? (body.photo_ext || 'jpg') : null;
const filename = hasFile ? `${Date.now()}-${Math.random().toString(36).slice(2, 8)}.${ext}` : null;

return [{
  json: {
    business_id: body.business_id,
    first_name: body.first_name,
    full_name: body.full_name || null,
    phone: body.phone || null,
    email: body.email || null,
    service_type: body.service_type || null,
    job_completion_date: body.job_completion_date || null,
    consent_optin: !!body.consent_optin,
    _hasFile: hasFile,
    _storageFilename: filename,
    _photoBase64: body.photo_base64 || null,
    _photoMimeType: body.photo_mime_type || 'image/jpeg'
  }
}];

