const response = items[0].json;
const parts = response?.candidates?.[0]?.content?.parts || [];
const imagePart = parts.find(p => p.inlineData || p.inline_data);
const inline = imagePart?.inlineData || imagePart?.inline_data;

const prepared = $('Prepare Filename').first().json;

if (!inline) {
  // Gemini failed to return an image — fall back to the original uploaded photo
  // rather than blocking the whole customer insert on a personalization failure.
  return [{
    json: prepared,
    binary: {
      photo: await this.helpers.prepareBinaryData(Buffer.from(prepared._photoBase64, 'base64'), prepared._storageFilename, prepared._photoMimeType)
    }
  }];
}

const mimeType = inline.mimeType || inline.mime_type || 'image/png';
const base64Data = inline.data;

return [{
  json: prepared,
  binary: {
    photo: await this.helpers.prepareBinaryData(Buffer.from(base64Data, 'base64'), prepared._storageFilename, mimeType)
  }
}];

const hasFile = $('Prepare Filename').first().json._hasFile;
const filename = $('Prepare Filename').first().json._storageFilename;
const publicUrl = hasFile
  ? `https://xbmoomufmxicwymwbovg.supabase.co/storage/v1/object/public/customer-project-images/${filename}`
  : null;

return [{
  json: {
    ...$('Prepare Filename').first().json,
    project_image_url: publicUrl
  }
}];

parameters.query:
insert into customers (
  business_id, first_name, full_name, phone, email,
  service_type, job_completion_date, consent_optin, source, project_image_url
) values (
  $1, $2, $3, $4, $5, $6, $7, $8, 'Business self-serve form (authenticated)', $9
)
returning id;
